function obterDados(url) {
    return new Promise((resolve, reject) => {
        if (!url) {
            reject(new Error('URL inválida'));
        } else {
            // Simulando uma chamada assíncrona
            setTimeout(() => {
                resolve(`Dados obtidos de ${url}`);
            }, 1000);
        }
    });
}

