def calcular_media(*notas, peso=1):
    if not notas:
        return 0
    return sum(nota * peso for nota in notas) / len(notas)

resultado = calcular_media(7, 8, 9)
print(resultado)

function buscaValor(raiz, valor) {
    if (raiz === null) return false;
    if (raiz.valor === valor) return true;
    return buscaValor(raiz.esquerda, valor) || buscaValor(raiz.direita, valor);
}

def busca_linear(lista, alvo):
    for i in range(len(lista)):
        if lista[i] == alvo:
            return i
    return -1

numeros = [10, 20, 30, 40, 50]
resultado = busca_linear(numeros, 30)
